{{ config(
            materialized='table',
                post_hook={
                    "sql": "TRUNCATE TABLE `kerala-ayurveda-wh.shoppass_in.fact_shopflo_identifed_events`; INSERT INTO `kerala-ayurveda-wh.shoppass_in.fact_shopflo_identifed_events` WITH unioned AS ( SELECT \'ka_india\' AS source_store, event_name, payload, received_at_ts FROM `kerala-ayurveda-wh.shoppass_in.raw_events_ka_india` UNION ALL SELECT \'avg_india\' AS source_store, event_name, payload, received_at_ts FROM `kerala-ayurveda-wh.shoppass_in.raw_events_avg_india` ), extracted AS ( SELECT FARM_FINGERPRINT(TO_JSON_STRING(payload)) AS event_id, source_store, event_name, COALESCE(JSON_VALUE(payload,\'$.sessionId\'), JSON_VALUE(payload,\'$.session_id\')) AS session_id, COALESCE(JSON_VALUE(payload,\'$.eventPayload.uiData.longSessionId\'), JSON_VALUE(payload,\'$.data.long_session_id\'), JSON_VALUE(payload,\'$.long_session_id\')) AS long_session_id, NULLIF(TRIM(COALESCE(JSON_VALUE(payload,\'$.eventPayload.userData.userId\'), JSON_VALUE(payload,\'$.data.user_data.userId\'), JSON_VALUE(payload,\'$.user_data.userId\'), JSON_VALUE(payload,\'$.customer.uid\'))),\'\') AS user_id, NULLIF(TRIM(COALESCE(JSON_VALUE(payload,\'$.eventPayload.userData.email\'), JSON_VALUE(payload,\'$.data.user_data.email\'), JSON_VALUE(payload,\'$.user_data.email\'), JSON_VALUE(payload,\'$.customer.email\'))),\'\') AS email, NULLIF(TRIM(COALESCE(JSON_VALUE(payload,\'$.eventPayload.userData.phone\'), JSON_VALUE(payload,\'$.data.user_data.phone\'), JSON_VALUE(payload,\'$.user_data.phone\'), JSON_VALUE(payload,\'$.customer.phone\'))),\'\') AS phone, NULLIF(TRIM(COALESCE(JSON_VALUE(payload,\'$.eventPayload.userData.firstName\'), JSON_VALUE(payload,\'$.data.user_data.firstName\'), JSON_VALUE(payload,\'$.user_data.firstName\'), JSON_VALUE(payload,\'$.customer.first_name\'))),\'\') AS first_name, NULLIF(TRIM(COALESCE(JSON_VALUE(payload,\'$.eventPayload.userData.lastName\'), JSON_VALUE(payload,\'$.data.user_data.lastName\'), JSON_VALUE(payload,\'$.user_data.lastName\'), JSON_VALUE(payload,\'$.customer.last_name\'))),\'\') AS last_name, SAFE_CAST(COALESCE(JSON_VALUE(payload,\'$.eventPayload.userData.marketingConsent\'), JSON_VALUE(payload,\'$.data.user_data.marketingConsent\'), JSON_VALUE(payload,\'$.user_data.marketingConsent\'), JSON_VALUE(payload,\'$.customer.marketing_consent\')) AS BOOL) AS marketing_consent, NULLIF(TRIM(COALESCE(JSON_VALUE(payload,\'$.eventPayload.userData.networkSpeed\'), JSON_VALUE(payload,\'$.data.user_data.networkSpeed\'), JSON_VALUE(payload,\'$.user_data.networkSpeed\'))),\'\') AS network_speed, COALESCE(JSON_VALUE(payload,\'$.eventPayload.uiData.pageTitle\'), JSON_VALUE(payload,\'$.data.product_name\'), JSON_VALUE(payload,\'$.data.page_title\'), JSON_VALUE(payload,\'$.cart_product_names\')) AS page_or_item_title, COALESCE(JSON_VALUE(payload,\'$.channel\'), JSON_VALUE(payload,\'$.data.channel\')) AS channel, COALESCE(JSON_VALUE(payload,\'$.eventPayload.uiData.pageUrl\'), JSON_VALUE(payload,\'$.data.page_url\')) AS page_url, COALESCE(JSON_VALUE(payload,\'$.eventPayload.uiData.landingPageUrl\'), JSON_VALUE(payload,\'$.data.landing_page_url\'), JSON_VALUE(payload,\'$.landing_page_url\')) AS landing_page_url, COALESCE(JSON_VALUE(payload,\'$.eventPayload.uiData.referrerPageUrl\'), JSON_VALUE(payload,\'$.data.referrer_page_url\')) AS referrer_page_url, COALESCE(JSON_QUERY(payload,\'$.eventPayload.uiData.utmParams\'), JSON_QUERY(payload,\'$.data.utm_data\')) AS utm_data, TIMESTAMP_MILLIS(SAFE_CAST(JSON_VALUE(payload,\'$.timestamp\') AS INT64)) AS event_ts, DATE(TIMESTAMP_MILLIS(SAFE_CAST(JSON_VALUE(payload,\'$.timestamp\') AS INT64)), \'Asia/Kolkata\') AS event_date_ist, received_at_ts, payload AS raw_payload FROM unioned ) SELECT event_id, source_store, event_name, session_id, long_session_id, user_id, email, phone, first_name, last_name, marketing_consent, network_speed, page_or_item_title, channel, page_url, landing_page_url, referrer_page_url, utm_data, (SELECT JSON_VALUE(u,\'$.value\') FROM UNNEST(JSON_QUERY_ARRAY(utm_data)) u WHERE JSON_VALUE(u,\'$.name\')=\'utm_source\') AS utm_source, (SELECT JSON_VALUE(u,\'$.value\') FROM UNNEST(JSON_QUERY_ARRAY(utm_data)) u WHERE JSON_VALUE(u,\'$.name\')=\'utm_medium\') AS utm_medium, (SELECT JSON_VALUE(u,\'$.value\') FROM UNNEST(JSON_QUERY_ARRAY(utm_data)) u WHERE JSON_VALUE(u,\'$.name\')=\'utm_campaign\') AS utm_campaign, (SELECT JSON_VALUE(u,\'$.value\') FROM UNNEST(JSON_QUERY_ARRAY(utm_data)) u WHERE JSON_VALUE(u,\'$.name\')=\'utm_content\') AS utm_content, (SELECT JSON_VALUE(u,\'$.value\') FROM UNNEST(JSON_QUERY_ARRAY(utm_data)) u WHERE JSON_VALUE(u,\'$.name\')=\'utm_term\') AS utm_term, (SELECT JSON_VALUE(u,\'$.value\') FROM UNNEST(JSON_QUERY_ARRAY(utm_data)) u WHERE JSON_VALUE(u,\'$.name\')=\'gclid\') AS gclid, (SELECT JSON_VALUE(u,\'$.value\') FROM UNNEST(JSON_QUERY_ARRAY(utm_data)) u WHERE JSON_VALUE(u,\'$.name\')=\'fbclid\') AS fbclid, event_ts, event_date_ist, received_at_ts, raw_payload, CURRENT_TIMESTAMP() AS bq_load_ts FROM extracted WHERE user_id IS NOT NULL OR email IS NOT NULL OR phone IS NOT NULL OR first_name IS NOT NULL OR last_name IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY event_id ORDER BY received_at_ts) = 1;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

